"""The README's results block, generated by ``pii-guard eval report`` (LAB-1239).

The README's compact leak table used to be copied by hand from ``docs/benchmarks.md`` and went
stale whenever a new run landed. Now ``pii-guard eval report`` rewrites the text between
:data:`START` and :data:`END` in ``README.md`` and ``--check`` fails when it is out of date.

What goes in the table is editorial, so it lives in the ``readme`` section of
``docs/benchmarks/config.json``; the numbers come from the same index and per-dataset counts
as ``docs/benchmarks.md``, rounded the same way::

    "readme": {
      "columns": [
        {"title": "Hand-written", "fixture_set": "smoke"},
        {"title": "Agent traffic", "dataset": "agent-traffic"}
      ],
      "rows": [
        {"system": "rules+ner:xlmr-base-v2-hn", "label": "**PII Guard fast**", "short": "fast",
         "marks": {"agent-traffic": "†"}},
        {"system": "rules", "label": "PII Guard rules only", "p50": false}
      ]
    }

A column reads either the latest snapshot of a fixture set (its pooled ``all`` leak) or the
latest per-dataset counts of a registered dataset (``eval/datasets/results/``). The lowest
leak in a column is bold, unless the best cell carries a caveat mark (an in-distribution
result is not a win). The block also says the hand-written set's detection p50 per row, the
first row's over-masking per column (LAB-1598: it used to be hand-copied prose under the
table, and went stale) and links the records behind the first row.
"""

from __future__ import annotations

from collections.abc import Mapping, Sequence
from typing import Any

from pii_guard.eval.record import RecordError
from pii_guard.eval.stats import fmt_duration

__all__ = ["END", "START", "parse_spec", "render_block", "splice"]

START = "<!-- results:start -->"
END = "<!-- results:end -->"
_NOTE = (
    "<!-- Generated by `pii-guard eval report` from the run records and the `readme` section "
    "of docs/benchmarks/config.json; edit those, not this block. -->"
)
_MISSING = "—"


def parse_spec(raw: object, where: str) -> dict[str, Any]:
    """Validate the config's ``readme`` section; :class:`RecordError` names what is wrong."""
    if not isinstance(raw, dict):
        raise RecordError(f"{where}: 'readme' must be an object")
    columns, rows = raw.get("columns"), raw.get("rows")
    if not isinstance(columns, list) or not columns or not isinstance(rows, list) or not rows:
        raise RecordError(f"{where}: 'readme' needs non-empty 'columns' and 'rows' lists")
    for col in columns:
        if (
            not isinstance(col, dict)
            or not isinstance(col.get("title"), str)
            or (("fixture_set" in col) == ("dataset" in col))
        ):
            raise RecordError(
                f"{where}: each readme column needs a 'title' and one of 'fixture_set' or "
                f"'dataset': {col!r}"
            )
    for row in rows:
        if not isinstance(row, dict) or not all(
            isinstance(row.get(k), str) for k in ("system", "label")
        ):
            raise RecordError(f"{where}: each readme row needs 'system' and 'label': {row!r}")
    return {"columns": columns, "rows": rows}


def _col_id(col: Mapping[str, Any]) -> str:
    return str(col.get("fixture_set") or col["dataset"])


def _pct(value: float | None) -> str:
    # Rounded as both tables in docs/benchmarks.md round (one decimal of the percentage).
    return _MISSING if value is None else f"{value * 100:.1f} %"


def _latest_counts(counts: Sequence[Mapping[str, Any]]) -> dict[tuple[str, str], Any]:
    latest: dict[tuple[str, str], Any] = {}
    for c in counts:  # oldest first, as load_counts returns them: the newest run wins
        latest[(c["dataset"], c["system"]["key"])] = c
    return latest


def _snapshot(index: Mapping[str, Any], fixture_set: str, system: str) -> Any:
    for s in index["snapshots"]:
        if s["fixture_set"] == fixture_set and s["system"] == system:
            return s
    return None


class _Cell:
    def __init__(
        self,
        value: float | None,
        docs: int | None,
        links: list[str],
        over: float | None = None,
    ) -> None:
        self.value, self.docs, self.links, self.over = value, docs, links, over


def _cell(
    index: Mapping[str, Any],
    latest: Mapping[tuple[str, str], Any],
    col: Mapping[str, Any],
    system: str,
) -> _Cell:
    if "fixture_set" in col:
        snap = _snapshot(index, col["fixture_set"], system)
        if snap is None:
            return _Cell(None, None, [])
        links = [f"eval/results/runs/{run_id}.json" for run_id in snap["run_ids"]]
        return _Cell(
            snap["all"]["leak"], snap["all"]["documents"], links, snap["all"].get("over_masking")
        )
    c = latest.get((col["dataset"], system))
    if c is None:
        return _Cell(None, None, [])
    summary = c["summary"]
    over = summary.get("over_masking")
    return _Cell(
        summary["leak"]["value"],
        summary["documents"],
        [f"eval/datasets/results/{c['run_id']}.json"],
        over.get("value") if isinstance(over, Mapping) else None,
    )


def _header(index: Mapping[str, Any], col: Mapping[str, Any], cells: Sequence[_Cell]) -> str:
    if "fixture_set" in col:
        info = index["fixture_sets"].get(col["fixture_set"])
        if info is None:
            return str(col["title"])
        langs = "+".join(info["documents"])
        return f"{col['title']} ({langs}, {sum(info['documents'].values())} docs)"
    docs = next((c.docs for c in cells if c.docs is not None), None)
    return f"{col['title']} ({docs})" if docs is not None else str(col["title"])


def _escape(text: str) -> str:
    return text.replace("|", "\\|").replace("\n", " ")


def render_block(
    index: Mapping[str, Any], counts: Sequence[Mapping[str, Any]], spec: Mapping[str, Any]
) -> str:
    """The text between the markers (without them): a pure function of its inputs."""
    columns, rows = spec["columns"], spec["rows"]
    latest = _latest_counts(counts)
    grid = [[_cell(index, latest, col, row["system"]) for col in columns] for row in rows]
    body: list[list[str]] = [[row["label"]] for row in rows]
    for j, col in enumerate(columns):
        cid = _col_id(col)
        shown = [_pct(grid[i][j].value) for i in range(len(rows))]
        marks = [str(row.get("marks", {}).get(cid, "")) for row in rows]
        numbers = [float(s[:-2]) for s in shown if s != _MISSING]
        best = min(numbers) if numbers else None
        winners = [i for i, s in enumerate(shown) if s != _MISSING and float(s[:-2]) == best]
        bold = bool(winners) and not any(marks[i] for i in winners)
        for i, text in enumerate(shown):
            cell = f"**{text}**" if bold and i in winners else text
            body[i].append(cell + (f" {marks[i]}" if marks[i] else ""))
    header = ["Leak"] + [_header(index, col, [g[j] for g in grid]) for j, col in enumerate(columns)]
    lines = [
        "| " + " | ".join(_escape(h) for h in header) + " |",
        "|---|" + "---:|" * len(columns),
        *("| " + " | ".join(_escape(c) for c in r) + " |" for r in body),
    ]
    out = [_NOTE, "", *lines, ""]

    p50 = []
    for row in rows:
        if row.get("p50", True) is False:
            continue
        for col in columns:
            if "fixture_set" not in col or col["fixture_set"] != index.get("headline_set"):
                continue
            snap = _snapshot(index, col["fixture_set"], row["system"])
            if snap is not None and snap["all"]["detect_p50_ms"] is not None:
                star = "*" if snap["all"]["latency_pooled"] else ""
                short = row.get("short", row["label"])
                p50.append(f"{short} {fmt_duration(snap['all']['detect_p50_ms'])}{star}")
            break
    if p50:
        out.append(
            f"Detection p50 on the `{index.get('headline_set')}` set: "
            + ", ".join(p50)
            + " (`*` averaged over several runs), each on the machine in its run record: "
            "compare loosely."
        )
        out.append("")

    first = rows[0]
    overs = [
        f"{col['title']} {_pct(grid[0][j].over)}"
        for j, col in enumerate(columns)
        if grid[0][j].over is not None
    ]
    if overs:
        out.append(
            f"Over-masking of the {first.get('short', first['label'])} row: "
            + ", ".join(overs)
            + " (share of masked spans that are not personal data; "
            "[how it is scored](docs/benchmarks.md#how-to-read-this))."
        )
        out.append("")

    refs = []
    for j, col in enumerate(columns):
        links = grid[0][j].links
        if len(links) == 1:
            refs.append(f"[{col['title']}]({links[0]})")
        elif links:
            refs.append(
                f"{col['title']} ("
                + " · ".join(f"[{k}]({link})" for k, link in enumerate(links, 1))
                + ")"
            )
    if refs:
        out.append(
            f"Records behind the {first.get('short', first['label'])} row: "
            + ", ".join(refs)
            + "; every other cell is in the [run log](docs/benchmarks.md#run-log) and "
            "[eval/datasets/results/](eval/datasets/results/)."
        )
    return "\n".join(out) + "\n"


def splice(doc: str, block: str, where: str) -> str:
    """``doc`` with the text between :data:`START` and :data:`END` replaced by ``block``."""
    start, end = doc.find(START), doc.find(END)
    if start < 0 or end < start or doc.count(START) != 1 or doc.count(END) != 1:
        raise RecordError(f"{where}: needs exactly one {START} ... {END} block")
    return doc[: start + len(START)] + "\n" + block + doc[end:]
